async def report( self, command: wire.BackendCommand, **kwargs: object ) -> control.ReportReceipt: calls.append(("report", command.command_id, kwargs["succeeded"])) return control.ReportReceipt(result=control.COMMAND_RESULT_ACCEPTED)
def finalize_command(self, command_id: str) -> None: calls.append(("finalize", command_id))
